begin;
create function pg_temp.ok(value boolean,label text)returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.denied(statement text,fragment text) returns void language plpgsql as $$begin begin execute statement;exception when others then if position(fragment in sqlerrm)>0 then raise notice 'PASS: blocked %',fragment;return;end if;raise;end;raise exception 'Unexpected acceptance: %',statement;end$$;
create function pg_temp.actor(uid uuid)returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);end$$;
do $$declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();tid uuid;e uuid;sid uuid;request uuid:=gen_random_uuid();pending uuid;begin
 insert into auth.users(id)values(a),(b),(c);insert into public.profiles(id,display_name)values(a,'QA receiver'),(b,'QA debtor'),(c,'QA manager');
 insert into public.trips(name,owner_id,start_date,end_date)values('QA offline rollback',a,current_date,current_date+1)returning id into tid;
 insert into public.trip_members(trip_id,user_id,trip_role,can_confirm_payments)values(tid,a,'owner',true),(tid,b,'member',false),(tid,c,'member',true);
 insert into public.expenses(trip_id,title,amount,paid_by,created_by)values(tid,'QA ordinary bill',100,a,a)returning id into e;
 insert into public.expense_participants(expense_id,user_id,share_amount)values(e,b,100);
 perform pg_temp.ok(not has_function_privilege('anon','public.record_offline_settlement(uuid,uuid,uuid,numeric,text,uuid)','execute'),'anonymous receipt blocked');
 perform pg_temp.actor(b);perform pg_temp.denied(format('select public.record_offline_settlement(%L,%L,%L,40,%L,%L)',tid,b,a,'cash',request),'เฉพาะผู้รับเงิน');
 perform pg_temp.actor(a);perform pg_temp.denied(format('select public.record_offline_settlement(%L,%L,%L,40,%L,%L)',tid,b,a,'',request),'หมายเหตุ');
 perform pg_temp.denied(format('select public.record_offline_settlement(%L,%L,%L,101,%L,%L)',tid,b,a,'cash',request),'ยอดค้าง');
 sid:=public.record_offline_settlement(tid,b,a,40,'cash received',request);
 perform pg_temp.ok((select status='confirmed' and amount=40 and receipt_method='offline' and receipt_note='cash received' and confirmed_by=a and submitted_by=a and slip_path is null and confirmed_at is not null from public.trip_settlements where id=sid),'receipt retains actor, note, timestamp without fabricated slip');
 perform pg_temp.ok(public.record_offline_settlement(tid,b,a,40,'cash received',request)=sid,'same request retry does not double deduct');
 perform pg_temp.denied(format('select public.record_offline_settlement(%L,%L,%L,41,%L,%L)',tid,b,a,'cash received',request),'รหัสรายการ');
 perform pg_temp.denied(format('select public.record_offline_settlement(%L,%L,%L,61,%L,%L)',tid,b,a,'cash',gen_random_uuid()),'ยอดค้าง');
 insert into public.trip_settlements(trip_id,from_user,to_user,amount,status,submitted_by)values(tid,b,a,60,'pending',b)returning id into pending;
 perform pg_temp.denied(format('select public.record_offline_settlement(%L,%L,%L,60,%L,%L)',tid,b,a,'cash',gen_random_uuid()),'สลิปรอตรวจ');
 perform public.review_settlement(pending,'rejected');perform pg_temp.actor(c);
 perform public.record_offline_settlement(tid,b,a,60,'transfer received by receiver',gen_random_uuid());
 perform pg_temp.ok((select sum(amount)=100 from public.trip_settlements where trip_id=tid and status='confirmed'),'authorized manager clears only remaining balance');
 perform pg_temp.ok(public.trip_fund_balance(tid)=0,'ordinary settlement never credits trip fund');
 perform pg_temp.denied(format('select public.record_offline_settlement(%L,%L,%L,1,%L,%L)',tid,b,a,'already clear',gen_random_uuid()),'ยอดค้าง');
 perform pg_temp.denied(format('update public.trip_settlements set receipt_note=%L where id=%L','rewrite',sid),'ประวัติรับเงิน');
 perform pg_temp.denied(format('select public.review_settlement(%L,%L)',sid,'rejected'),'ยืนยันรับเงินแล้ว');
 -- Fund-funded portion is excluded and a collection-linked bill is never settled twice.
 insert into public.expenses(trip_id,title,amount,paid_by,created_by,fund_paid_satang)values(tid,'QA partially funded',100,a,a,4000)returning id into e;
 insert into public.expense_participants(expense_id,user_id,share_amount)values(e,b,100);
 perform public.record_offline_settlement(tid,b,a,60,'remaining personal portion',gen_random_uuid());
 perform pg_temp.denied(format('select public.record_offline_settlement(%L,%L,%L,1,%L,%L)',tid,b,a,'fund portion',gen_random_uuid()),'ยอดค้าง');
 insert into public.expenses(trip_id,title,amount,paid_by,created_by)values(tid,'QA collection-linked',100,a,a)returning id into e;
 insert into public.expense_participants(expense_id,user_id,share_amount)values(e,b,100);
 insert into public.collections(trip_id,title,amount,receiver_id,created_by,expense_id)values(tid,'QA separate collection',100,a,a,e);
 perform pg_temp.denied(format('select public.record_offline_settlement(%L,%L,%L,1,%L,%L)',tid,b,a,'collection debt',gen_random_uuid()),'ยอดค้าง');
end$$;
rollback;
